-- Generated by crux (matugen) — Hyprland border colors.
-- Same shape/paths noctalia's own noctalia-colors.lua used (hyprland.lua's
-- `dofile(...).apply_theme()` boot line and windowrules.lua's
-- `require("noctalia")` both already point at these two files — kept
-- as-is here rather than renamed, since renaming means also editing both
-- call sites for no functional benefit).

local primary = "rgb({{colors.primary.default.hex_stripped}})"
local surface = "rgb({{colors.surface.default.hex_stripped}})"
local secondary = "rgb({{colors.secondary.default.hex_stripped}})"
local error = "rgb({{colors.error.default.hex_stripped}})"

local function apply_theme()
    hl.config({
        general = {
            col = {
                active_border = { colors = { primary, secondary }, angle = 45 },
                inactive_border = surface,
            },
        },

        group = {
            col = {
                border_active = secondary,
                border_inactive = surface,
                border_locked_active = error,
                border_locked_inactive = surface,
            },

            groupbar = {
                col = {
                    active = secondary,
                    inactive = surface,
                    locked_active = error,
                    locked_inactive = surface,
                },
            },
        },
    })
end

return {
    colors = {
        primary = primary,
        surface = surface,
        secondary = secondary,
        error = error,
    },
    apply_theme = apply_theme
}
